parameters.jsCode:
const body = $json.body || {};
if (!body.creator_id || !body.message) {
  return [{
    valid: false,
    error_msg: "Missing required creator_id or message in request body.",
    creator_id: body.creator_id || null
  }];
}
return [{
  valid: true,
  creator_id: body.creator_id,
  message: body.message,
  gemini_api_key: body.gemini_api_key || null
}];

const creator = $('Fetch Creator Profile').first()?.json;
const scores = $('Fetch Creator Scores').first()?.json;
const analysis = $('Fetch Creator AI Analysis').first()?.json;
const input = $('Validate Input').first().json;

// Check if profile and analysis exists
if (!creator || !scores || !analysis) {
  return [{
    has_data: false,
    creator_id: input.creator_id,
    message: input.message,
    gemini_api_key: input.gemini_api_key,
    reason: "Profile has not been enrichment initialized yet."
  }];
}

return [{
  has_data: true,
  creator_id: input.creator_id,
  message: input.message,
  gemini_api_key: input.gemini_api_key,
  context: {
    full_name: creator.full_name || 'N/A',
    bio: creator.bio || 'N/A',
    city: creator.city || 'N/A',
    state: creator.state || 'N/A',
    categories: Array.isArray(creator.categories) ? creator.categories.join(', ') : 'N/A',
    languages: Array.isArray(creator.languages) ? creator.languages.join(', ') : 'N/A',
    followers_count: creator.followers_count || 0,
    engagement_rate: creator.engagement_rate || 0,
    average_views: creator.average_views || 0,
    profile_status: creator.profile_status || 'Incomplete',
    ai_status: creator.ai_status || 'Not Started',

    // Scores
    intelligence_score: scores.intelligence_score !== undefined ? scores.intelligence_score : 'N/A',
    audience_trust: scores.audience_trust !== undefined ? scores.audience_trust : 'N/A',
    engagement_rate_score: scores.engagement_rate_score !== undefined ? scores.engagement_rate_score : 'N/A',
    regional_influence: scores.regional_influence !== undefined ? scores.regional_influence : 'N/A',
    content_consistency: scores.content_consistency !== undefined ? scores.content_consistency : 'N/A',
    brand_readiness: scores.brand_readiness !== undefined ? scores.brand_readiness : 'N/A',
    ai_explanation: scores.ai_explanation || 'N/A',

    // Analysis
    profile_summary: analysis.profile_summary || 'N/A',
    profile_completeness: analysis.profile_completeness !== undefined ? analysis.profile_completeness : 'N/A',
    strengths: Array.isArray(analysis.strengths) ? analysis.strengths.join(', ') : 'N/A',
    weaknesses: Array.isArray(analysis.weaknesses) ? analysis.weaknesses.join(', ') : 'N/A',
    missing_information: Array.isArray(analysis.missing_information) ? analysis.missing_information.join(', ') : 'N/A'
  }
}];

